param([switch]$SelfTest)
$ErrorActionPreference='Stop'
$repoRoot=Split-Path $PSScriptRoot -Parent
Import-Module (Join-Path $PSScriptRoot 'DevelopmentEnvelopePreparation.psm1') -Force
Import-Module (Join-Path $PSScriptRoot 'lib\MorphospaceProtocolCommon.psm1') -Force
function Assert-Preparation([bool]$ok,[string]$message){if(-not$ok){throw "Development-envelope preparation self-test failed: $message"}}
function Write-PreparationJson([string]$path,[object]$value){[IO.Directory]::CreateDirectory((Split-Path $path -Parent))|Out-Null;[IO.File]::WriteAllText($path,(($value|ConvertTo-Json -Depth 64)+"`n"),[Text.UTF8Encoding]::new($false))}
function Copy-Preparation([object]$value){$value|ConvertTo-Json -Depth 64|ConvertFrom-Json}
function Hash([object]$value){Get-MorphospaceCanonicalJsonSha256 $value}
$temp=Join-Path ([IO.Path]::GetTempPath()) ('workenv-preparation-'+[guid]::NewGuid().ToString('N'))
try {
  $ws=Join-Path $temp 'morphospace';[IO.Directory]::CreateDirectory((Join-Path $ws 'iteration-units'))|Out-Null;[IO.Directory]::CreateDirectory((Join-Path $ws 'receipts'))|Out-Null
  $source=Join-Path $temp 'planning-source';[IO.Directory]::CreateDirectory($source)|Out-Null;& git -C $temp init $source|Out-Null;& git -C $source config user.name 'Preparation Test';& git -C $source config user.email 'preparation@example.invalid';[IO.File]::WriteAllText((Join-Path $source 'README.md'),'fixture',[Text.UTF8Encoding]::new($false));& git -C $source add README.md;& git -C $source commit -m fixture|Out-Null
  $commit=(& git -C $source rev-parse HEAD).Trim().ToLowerInvariant();$tree=(& git -C $source rev-parse 'HEAD^{tree}').Trim().ToLowerInvariant()
  $project=[ordered]@{schema='rusty.morphospace.workflow.project_spec.v2';project_id='portable-envelope';revision=1;owner='owner';purpose='portable fixture';activation_model=[ordered]@{default='disabled';unlisted_modules='inert';runtime_rule='selected-lock-and-runtime-input'};composition=[ordered]@{selected_features=@();denied_features=@();selected_modules=@();denied_modules=@();allowed_permissions=@();denied_permissions=@();data_classes=@()};authority_map=@([ordered]@{parameter='project.composition';owner='owner';adapters=@()});repositories=@([ordered]@{repo_id='planning';role='planning';path='.';allowed_paths=@('morphospace/')});modules=@();non_scope=@('fixture-only');validation_profiles=@([ordered]@{profile_id='quick';commands=@('fixture')});acceptance_profiles=@([ordered]@{profile_id='rollback';commands=@('fixture')});release_policy=[ordered]@{versioning='semver';commit_policy='fixture';push_checkpoint='none';source_first=$true;planning_last=$true;force_push_allowed=$false};public_boundary=[ordered]@{mode='mixed';private_overlay='local/';prohibited_evidence=@('private-identities')}}
  $emptyEffects=[ordered]@{permissions=@();services=@();activities=@();queries=@();tools=@();assets=@();shaders=@();native_libraries=@();commands=@();routes=@();streams=@();inputs=@();scenes=@();markers=@()};function New-FixtureFeature([string]$id){[ordered]@{feature_id=$id;module_id=$id;version='1';owner_lane='owner';selected=$true;run_activation_default='disabled';descriptor=[ordered]@{path=('features/'+$id+'.json');sha256=('0'*64);source_repo='planning';source_revision=$commit;source_path=('features/'+$id+'.json');source_sha256=('0'*64)};dependencies=@();conflicts=@();exclusive_group=$null;effects=(Copy-Preparation $emptyEffects);parameter_authorities=@();activation=[ordered]@{rule='selected-lock-and-runtime-input';runtime_inputs=@('fixture-input');receipt_schema='fixture.receipt';effective_marker='fixture.marker'};validation_profile='quick';rollback_profile='rollback'}};$provider=New-FixtureFeature 'morphovision-debug-host-receipt-provider';$lock=[ordered]@{schema='rusty.morphospace.workflow.feature_lock.v2';project_id='portable-envelope';project_revision=1;revision=1;generated_at='2026-08-25T00:00:00Z';resolver_version='rusty-morphospace-feature-resolver/2';lock_fingerprint=('0'*64);default_activation='disabled';activation_rule='selected-lock-and-runtime-input';selected_features=@('morphovision-debug-host-receipt-provider');denied_features=@();features=@($provider);effect_union=(Copy-Preparation $emptyEffects)}
  $state=[ordered]@{schema='rusty.morphospace.workflow.workspace_state.v2';project_id='portable-envelope';plan_revision=1;current_unit=$null;next_ready_unit=$null;last_event_id='u001-accepted';last_accepted_receipt='receipts/u001-accepted.json';repository_heads=@();repository_checkpoints=@();module_registry=[ordered]@{lock_revision=1;lock_fingerprint=('0'*64);modules=@()};capability_registry=@();dirty_repositories=@();blockers=@();validation_checkpoint=$null;pending_push_bundle=$null};$u001=[ordered]@{project_id='portable-envelope';unit_id='u001';status='accepted'}
