  $targetLock=Copy-Preparation $lock;$targetLock.project_revision=2;$targetLock.revision=2;$feature=New-FixtureFeature 'projection-stack-stabilization';$targetLock.features+=,$feature;$targetLock.selected_features=@('morphovision-debug-host-receipt-provider','projection-stack-stabilization');$targetLock.effect_union.permissions=@('CAMERA','HEADSET_CAMERA','SPATIAL_CAMERA','USE_SCENE','OPENXR','OPENXR_SYSTEM')
  $eventsPath=Join-Path $ws 'iteration-events.jsonl';$input=[ordered]@{schema='rusty.morphospace.workflow.development_envelope_preparation.v1';preparation_id='portable-envelope-prepare';project_id='portable-envelope';predecessor_unit_id='u001';envelope=[ordered]@{project=$targetProject;feature_lock=$targetLock;owner_repositories=@([ordered]@{repo_id='planning';source_roots=@('morphospace/')});public_private_boundary='mixed';allowed_change_categories=@('implementation','validation','documentation-only');allowed_effect_categories=@('filesystem','build','device');allowed_permission_categories=@('CAMERA','HEADSET_CAMERA','SPATIAL_CAMERA','USE_SCENE','OPENXR','OPENXR_SYSTEM');build_envelope=[ordered]@{class='product';allowed_profiles=@('quick-host','raw-projection-devfast','raw-projection-candidate','maximum-blend-control-candidate')};device_envelope=[ordered]@{requirement='required';allowed_kinds=@('quest-typed-deploy-launch-observe-stop','raw-projection-freshness','maximum-blend-fixed-90hz-cpu4-gpu4-ababa')};source_composition=[ordered]@{path='source-composition/prepared.json';repository_ids=@('planning')}};expected=[ordered]@{project_sha256=(Hash $project);state_sha256=(Hash $state);feature_lock_sha256=(Hash $lock);repository_map_path='repository-map.json';repository_map_sha256=(Get-MorphospaceFileSha256 (Join-Path $ws 'repository-map.json'));predecessor_unit_path='iteration-units/u001.json';predecessor_unit_sha256=(Hash $u001);events_sha256=(Get-MorphospaceFileSha256 $eventsPath);events_length=([IO.FileInfo]$eventsPath).Length;event_tail_id='u001-accepted'};does_not_prove=@('Does not admit a future unit or execute a device action.')}
  $inputPath=Join-Path $temp 'prepare.json';Write-PreparationJson $inputPath $input;$out=Join-Path $ws 'receipts\portable-envelope-prepare.json';$dry=Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $ws -DevelopmentEnvelopePreparation $inputPath -OutPath $out -Timestamp '2026-08-25T00:01:00.0000000Z';$inputHash=Get-MorphospaceFileSha256 $inputPath;$recoveryBase=Join-Path $temp 'recovery-base';Copy-Item $ws $recoveryBase -Recurse;$run=Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $ws -DevelopmentEnvelopePreparation $inputPath -ExpectedDevelopmentEnvelopePreparationSha256 $inputHash -OutPath $out -Timestamp '2026-08-25T00:01:00.0000000Z' -Execute;$automationReceiptV2=Join-Path (Split-Path $PSScriptRoot -Parent) 'schemas\work-unit-automation-receipt-v2.schema.json';Assert-Preparation ((Test-Json -Json ($dry|ConvertTo-Json -Depth 32 -Compress) -SchemaFile $automationReceiptV2)-and(Test-Json -Json ($run|ConvertTo-Json -Depth 32 -Compress) -SchemaFile $automationReceiptV2)) 'development-envelope owner emitted a receipt outside the shared v2 schema';Assert-Preparation ($run.executed-and(Test-Path $out)-and(Test-Path (Join-Path $ws 'source-composition\prepared.json'))-and$null-eq(Read-MorphospaceProtocolJson (Join-Path $ws 'workspace.state.json')).current_unit-and-not(Test-Path (Join-Path $ws 'iteration-units\u002.json'))) 'positive idle preparation did not preserve idle no-future-unit state'
  $dryReplay=Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $ws -DevelopmentEnvelopePreparation $inputPath -ExpectedDevelopmentEnvelopePreparationSha256 $inputHash -OutPath $out;Assert-Preparation (-not$dryReplay.executed-and$null-eq$dryReplay.event_id-and(Test-Json -Json ($dryReplay|ConvertTo-Json -Depth 32 -Compress) -SchemaFile $automationReceiptV2)) 'existing-intent dry preparation replay claimed execution/event or failed receipt-v2';$replay=Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $ws -DevelopmentEnvelopePreparation $inputPath -ExpectedDevelopmentEnvelopePreparationSha256 $inputHash -OutPath $out -Execute;Assert-Preparation ($replay.executed-and$null-ne$replay.event_id-and(Test-Json -Json ($replay|ConvertTo-Json -Depth 32 -Compress) -SchemaFile $automationReceiptV2)) 'exact preparation replay was not idempotent and schema-valid'
  foreach($cut in @('after-intent','after-artifacts','after-project','after-lock','after-state','after-event')){$root=Join-Path $temp ("recovery-"+$cut);Copy-Item $recoveryBase $root -Recurse;$cutOut=Join-Path $root 'receipts\portable-envelope-prepare.json';$interrupted=$false;try{Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $root -DevelopmentEnvelopePreparation $inputPath -ExpectedDevelopmentEnvelopePreparationSha256 $inputHash -OutPath $cutOut -Execute -FaultAfter $cut|Out-Null}catch{$interrupted=$true};$resumed=Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $root -DevelopmentEnvelopePreparation $inputPath -ExpectedDevelopmentEnvelopePreparationSha256 $inputHash -OutPath $cutOut -Execute;Assert-Preparation ($interrupted-and$resumed.executed-and(Test-Path $cutOut)-and(Test-Path (Join-Path $root 'receipts\transactions\portable-envelope-prepare-prepared-transition.completion.json'))) "recovery cut '$cut' did not resume its exact preparation intent"}
  $providerRoot=Join-Path $temp 'damage-provider-rewrite';Copy-Item $recoveryBase $providerRoot -Recurse;$providerRewrite=Copy-Preparation $input;$providerRewrite.envelope.feature_lock.features[0].version='2';$providerRewritePath=Join-Path $temp 'damage-provider-rewrite.json';Write-PreparationJson $providerRewritePath $providerRewrite;$providerRejected=$false;try{Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $providerRoot -DevelopmentEnvelopePreparation $providerRewritePath -OutPath (Join-Path $providerRoot 'receipts\portable-envelope-prepare.json')|Out-Null}catch{$providerRejected=$_.Exception.Message-ceq"Preparation rewrites existing feature 'morphovision-debug-host-receipt-provider'."};Assert-Preparation $providerRejected 'accepted rewrite of a prefixed predecessor feature or returned the wrong rejection'
  $duplicateRoot=Join-Path $temp 'damage-duplicate-predecessor';Copy-Item $recoveryBase $duplicateRoot -Recurse;$duplicateLock=Read-MorphospaceProtocolJson (Join-Path $duplicateRoot 'feature.lock.json');$duplicateLock.features+=,(Copy-Preparation $duplicateLock.features[0]);Write-PreparationJson (Join-Path $duplicateRoot 'feature.lock.json') $duplicateLock;$duplicateInput=Copy-Preparation $input;$duplicateInput.expected.feature_lock_sha256=Hash $duplicateLock;$duplicateInputPath=Join-Path $temp 'damage-duplicate-predecessor.json';Write-PreparationJson $duplicateInputPath $duplicateInput;$duplicateRejected=$false;try{Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $duplicateRoot -DevelopmentEnvelopePreparation $duplicateInputPath -OutPath (Join-Path $duplicateRoot 'receipts\portable-envelope-prepare.json')|Out-Null}catch{$duplicateRejected=$_.Exception.Message-ceq"Preparation current feature lock repeats 'morphovision-debug-host-receipt-provider'."};Assert-Preparation $duplicateRejected 'accepted a duplicate prefixed predecessor feature or returned the wrong rejection'
  foreach($damage in @('permission','root','future-unit')){$root=Join-Path $temp ("damage-"+$damage);Copy-Item $ws $root -Recurse;$d=Copy-Preparation $input;if($damage-eq'permission'){$d.envelope.allowed_permission_categories+=,'INTERNET'}elseif($damage-eq'root'){$d.envelope.owner_repositories[0].source_roots=@('../outside/')}else{Write-PreparationJson (Join-Path $root 'iteration-units\future.json') ([ordered]@{unit_id='future'})};$path=Join-Path $temp ("damage-"+$damage+'.json');Write-PreparationJson $path $d;$rejected=$false;try{Invoke-MorphospacePrepareDevelopmentEnvelope -WorkspaceRoot $root -DevelopmentEnvelopePreparation $path -OutPath (Join-Path $root 'receipts\portable-envelope-prepare.json')|Out-Null}catch{$rejected=$true};Assert-Preparation $rejected "accepted $damage damage"}
  Write-Host 'Development-envelope preparation self-test passed.'
} finally {if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
